<script setup lang="ts">
import {computed} from 'vue';import {t,date} from './lib';
const props=defineProps<{state:any;compact?:boolean;pending?:boolean}>();
const reason=computed(()=>props.pending?t('Checking ingestion status…','正在确认接入状态…'):({ready:t('New data can be accepted','可新增接入'),free_period_refresh:t('New data can be accepted; the free period refreshes on ingestion','可新增接入，免费账期将在接入时更新'),overage_ready:t('Authorized overage active','已启用授权超额接入'),period_ended:t('New data paused: billing period ended','新增接入暂停：账期已结束'),subscription_inactive:t('New data paused: subscription inactive','新增接入暂停：订阅未生效'),payment_pending:t('New data paused: payment needs confirmation','新增接入暂停：付款待确认'),overage_cap:t('New data paused: overage cap reached','新增接入暂停：已达超额上限'),quota_exhausted:t('New data paused: quota exhausted','新增接入暂停：额度已用尽')} as Record<string,string>)[props.state?.reason]||t('Ingestion status unavailable','接入状态暂不可用'));
const subscription=computed(()=>({active:t('Active','有效'),canceled:t('Cancelled','已取消'),past_due:t('Past due','已逾期'),paused:t('Paused','已暂停'),unpaid:t('Unpaid','未付款'),none:t('No paid subscription','无付费订阅')} as Record<string,string>)[props.state?.subscription_status]||props.state?.subscription_status);
</script>
<template><div :class="[compact?'ingestion-compact':'notice ingestion-notice',{'error':state&&state.can_accept_new===false}]" role="status"><strong>{{reason}}</strong><template v-if="!compact"><p v-if="subscription">{{t('Subscription','订阅状态')}}: {{subscription}} · {{t('Billing period ends','账期结束')}}: {{date(state.period_end)}}</p><p v-if="state?.grace_until">{{t('Renewal grace ends','续费宽限截止')}}: {{date(state.grace_until)}}</p><p>{{t('This is a quota and subscription snapshot for new objects, not a guarantee for every request. Existing-object updates still require valid keys, revisions and retained data. The API response is authoritative.','这是针对新增对象的额度与订阅状态快照，不保证每次请求都成功；已有对象更新仍须满足密钥、修订版本和保留期规则，以接口结果为准。')}}</p></template><RouterLink v-if="!state||!state.can_accept_new" to="/app/billing">{{t('Review billing and quota','查看套餐与额度')}}</RouterLink></div></template>
